/**
 * THE CONTENT-DEPENDENCY INVENTORY.
 *
 * Every assertion in this suite, classified by what it actually depends on, so
 * that when API-020-ST publishes its change set the impact is a LOOKUP rather
 * than a discovery.
 *
 * WHY THIS EXISTS. The step-4a re-pin dry run concluded "three commands and no
 * code", on the grounds that the assertions are on content rather than
 * identifiers. That was tested against a three-rename change set. The real one
 * is eight hierarchy renames, three management entities with no seeded
 * counterpart, and STORY TEXT moving with them — `Block B, 18/F, Flat B4`
 * becomes `3/F, Flat B2`. Story text is content, so "my assertions are on
 * content" stopped being the reason the re-pin was cheap and became the reason
 * it might not be.
 *
 * THE CLASSES
 *
 *   structural         shape, count, presence, ordering, state. Survives a
 *                      rename of anything, because it never reads a value.
 *   content-stable     copy this client authors. Unaffected by the corpus.
 *   content-derived    a literal that ORIGINATES IN A FIXTURE. The exposed class.
 *   content-derived-external
 *                      a literal from severity.json, pemo_colors.dart or the
 *                      contract. Content-derived, but NOT in the corpus and
 *                      therefore not exposed to this re-pin. Separated rather
 *                      than folded into either neighbour, because folding it
 *                      into `structural` would understate the real exposure and
 *                      folding it into `content-derived` would overstate it.
 *
 * A test that touches more than one class is filed under its STRONGEST
 * exposure — the honest direction.
 *
 * NOTHING HERE IS A FIX. The change set does not exist yet, and an assertion
 * rewritten against a guess is worse than one that breaks honestly.
 */

export type DependencyClass =
  | 'structural'
  | 'content-stable'
  | 'content-derived'
  | 'content-derived-external';

export interface InventoryEntry {
  /** The exact `test(...)` argument as it appears in source. The completeness key. */
  key: string;
  file: string;
  /** How many assertions this call site produces (loops expand). */
  count: number;
  cls: DependencyClass;
  /** For content-derived: the fixture field the literal comes from. */
  field?: string;
  /** For content-derived: the literal the assertion expects. */
  expects?: string;
  note?: string;
}

