export function tally(): Record<DependencyClass, number> {
  const t: Record<DependencyClass, number> = {
    structural: 0, 'content-stable': 0, 'content-derived': 0, 'content-derived-external': 0,
  };
  for (const e of INVENTORY) t[e.cls] += e.count;
  return t;
}
